    async def cancel(self, id: str, *, request_options: typing.Optional[RequestOptions] = None) -> Email:
        """
        Cancels an email sent with a future `scheduled_at` before it is sent. Canceling an already canceled email returns it unchanged. To send it at another time, reschedule it instead.

        Parameters
        ----------
        id : str
            The email's id.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        Email
            The canceled email.

        Examples
        --------
        import asyncio

        from coss import AsyncCoss

        client = AsyncCoss(
            "2026-10-10",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.email.cancel(
                id="email_01k7c8m4q2f3e9v6t5r1n0p8yz",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.cancel(id, request_options=request_options)
        return _response.data

    async def reschedule(
        self, id: str, *, scheduled_at: dt.datetime, request_options: typing.Optional[RequestOptions] = None
    ) -> Email:
        """
        Moves an email sent with a future `scheduled_at` to a new time, at most 30 days from now, and records an `email.rescheduled` event. A time that is not in the future sends it within seconds. Rescheduling to the time it already has returns it unchanged. The domain and the suppression list are still checked when it is sent.

        Parameters
        ----------
        id : str
            The email's id.

        scheduled_at : dt.datetime
            The new time to send the email at (ISO 8601 with an offset, at most 30 days ahead). A time that is not in the future sends it right away.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        Email
            The rescheduled email.

        Examples
        --------
        import asyncio
        import datetime

        from coss import AsyncCoss

        client = AsyncCoss(
            "2026-10-10",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.email.reschedule(
                id="email_01k7c8m4q2f3e9v6t5r1n0p8yz",
                scheduled_at=datetime.datetime.fromisoformat(
                    "2026-10-12 09:00:00+00:00",
                ),
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.reschedule(id, scheduled_at=scheduled_at, request_options=request_options)
        return _response.data

    async def list_events(self, id: str, *, request_options: typing.Optional[RequestOptions] = None) -> EmailEventList:
        """
        Every delivery event of the email, oldest first: `email.scheduled`, `email.rescheduled`, `email.canceled`, `email.sent` and `email.failed` for the whole email, and `email.delivered`, `email.delivery_delayed`, `email.bounced`, `email.complained` and `email.suppressed` (skipped because of the suppression list) per recipient, plus `email.opened` and `email.clicked` when tracking is on (attributed to a recipient only when the email had a single one) and `email.unsubscribed` after a one-click unsubscribe.

        Parameters
        ----------
        id : str
            The email's id.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        EmailEventList
            The email's events.

        Examples
        --------
        import asyncio

        from coss import AsyncCoss

        client = AsyncCoss(
            "2026-10-10",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.email.list_events(
                id="email_01k7c8m4q2f3e9v6t5r1n0p8yz",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.list_events(id, request_options=request_options)
        return _response.data

